import androidx.biometric.BiometricPrompt
import androidx.fragment.app.FragmentActivity
import java.util.concurrent.Executors
fun bio(activity:FragmentActivity,onOk:()->Unit,onFail:()->Unit){
  val info=BiometricPrompt.PromptInfo.Builder().setTitle("{{title}}").setSubtitle("{{subtitle}}").setNegativeButtonText("Cancel").build()
  val p=BiometricPrompt(activity,Executors.newSingleThreadExecutor(),object:BiometricPrompt.AuthenticationCallback(){
    override fun onAuthenticationSucceeded(r:BiometricPrompt.AuthenticationResult){onOk()}
    override fun onAuthenticationFailed(){onFail()}})
  p.authenticate(info)}
